basicCode.vanilla:
import { createActivityGraph } from '@/components/ui/activity-graph';

const activityGraph = createActivityGraph({
  days: atividade,
  start: '2026-01-01',
  end: '2026-03-31',
  thresholds: [1, 4, 8, 13],
  status: 'complete',
  labels: rotulos,
});

// Sem janela, ou sem escala, não há grade — e a fábrica devolve nada. Sem
// ATIVIDADE, no entanto, há: um período em que nada aconteceu é a resposta.
if (activityGraph) document.querySelector('#app')?.append(activityGraph);

