withLabelsCode.vanilla:
// A JANELA E A ESCALA SÃO DADO, e os rótulos são texto de interface — nenhum
// dos dois é a fala do agente.
//
// O NOME DA CAMADA QUE ROLA é obrigatório: a grade é mais larga que a conversa,
// então ela rola, e o que rola é parada de teclado. Sem nome, quem chega ali
// ouvindo não sabe onde entrou.
//
// A PALAVRA DE CADA NÍVEL é o que impede a força da tinta de ser só cor: são
// tantas palavras quantos são os degraus da escala, MAIS UMA para o nível zero.
//
// Os meses vêm em duas formas porque servem a duas leituras: a curta rotula a
// coluna para o olho, e a longa entra na frase que quem ouve recebe.
const rotulos = {
  region: 'Atividade do trimestre',
  total: '{count} contribuições entre {start} e {end}',
  dateFormat: '{day} de {month} de {year}',
  monthsShort: ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'],
  monthsLong: ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'],
  weekdaysShort: ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'],
  none: 'Sem atividade em {date}.',
  one: '{count} contribuição em {date}. Intensidade {level}.',
  many: '{count} contribuições em {date}. Intensidade {level}.',
  levels: ['Nenhuma', 'Baixa', 'Média', 'Alta', 'Muito alta'],
  legendLess: 'Menos',
  legendMore: 'Mais',
};

