extensibilityCode.vanilla:
// A JANELA É DADO, e é o que esta peça tem que um mapa de calor fixo não tem:
// nada aqui olha o relógio, então pedir o trimestre passado é trocar duas
// cadeias. Trocar a janela é remontar a peça com outra janela — o componente
// desenha o que recebe.
function mostrarTrimestre(inicio, fim) {
  const proxima = createActivityGraph({
    days: atividade,
    start: inicio,
    end: fim,
    thresholds: [1, 4, 8, 13],
    status: 'complete',
    labels: rotulos,
  });
  if (proxima) grade.replaceWith(proxima);
}

