// A JANELA É DADO, e é o que esta peça tem que um mapa de calor fixo não tem:
// nada aqui olha o relógio, então pedir o trimestre passado é trocar duas
// cadeias. O componente desenha o que recebe.
//
// TUDO É MEMBRO DE CLASSE, e nenhum deles é constante no topo do arquivo:
// expressão de template só enxerga membro, e um binding para uma constante
// importada não resolve.
readonly atividade: readonly ActivityDay[] = [/* o que aconteceu, dia a dia */];

readonly degraus: readonly number[] = [1, 4, 8, 13];

readonly janela = signal({ start: '2026-01-01', end: '2026-03-31' });

// No template, a janela entra como os membros que são:
//
//   <div
//     ndsActivityGraph
//     [days]="atividade"
//     [start]="janela().start"
//     [end]="janela().end"
//     [thresholds]="degraus"
//     status="complete"
//     [labels]="rotulos"
//   ></div>

customizationCode.web:
.nds-activity-graph {
  /* O TAMANHO DA CASA, e é ele que decide quando a grade passa a ser mais larga
     que a conversa. Altura fixa é legítima aqui porque a casa não carrega texto
     — o que ela carrega é a frase que só quem ouve recebe. */
  --activity-graph-cell: var(--spacing-2);
  /* O vão entre casas, que é o que faz a grade parecer uma grade. */
  --activity-graph-gap: var(--spacing-px);
}
